<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useCatalog} from '../stores/catalog'
import {generateOpenApi,operationIds,specFilename} from '../services/openapi'
import {tddMarkdown} from '../services/templates'
import {download,slug} from '../utils/common'
import type {Template} from '../types'
const s=useCatalog(),route=useRoute(),router=useRouter(),query=ref(''),selected=ref(String(route.query.id||s.apis[0]?.id||'')),templateId=ref('process'),previewOpen=ref(false)
const processTemplate:Template={id:'process',name:'Process Type Technical Design (APIM)',desc:'Confluence-style technical design with tracking, constraints, data architecture, SLAs and approvals.',builtIn:true,enabled:true,content:'# {{api.name}} — {{api.version}}\n\n## Overview\n{{api.description}}\n\n## Tracking\n- Owning team: {{api.team}}\n- Gateway suffix: {{api.suffix}}\n- Backend: {{api.backend}}\n\n## Constraints and risks\n[TBD: constraints, risks and dependencies]\n\n## Data architecture\n[TBD: request, response and integration flow]\n\n## Operations\n{{api.operations}}\n\n## Security\n{{api.auth}}\n\n## SLAs and monitoring\n[TBD: volume, latency, availability and alerts]\n\n## Approvals\n[TBD: reviewers and approval date]'}
const templates=computed(()=>[processTemplate,...s.templates])
watch(()=>route.query.id,id=>{if(id)selected.value=String(id)})
const choices=computed(()=>s.apis.filter(a=>(a.name+' '+a.team+' '+a.backend+' '+a.desc).toLowerCase().includes(query.value.toLowerCase())))
const api=computed(()=>s.apis.find(a=>a.id===selected.value)||s.apis[0])
const template=computed(()=>templates.value.find(t=>t.id===templateId.value)||templates.value[0])
const yaml=computed(()=>api.value?generateOpenApi(api.value):'')
const tdd=computed(()=>api.value&&template.value?tddMarkdown(api.value,template.value):'')
const ids=computed(()=>api.value?operationIds(api.value):[])
const lastPr=computed(()=>api.value?[...s.prs].find(p=>p.apiId===api.value!.id):undefined)
const tbdCount=computed(()=>tdd.value.match(/\[TBD[^\]]*\]/g)?.length||0)
const templateDescription=computed(()=>template.value?.desc||'Generate a reusable technical design document from the API contract.')
const previewHtml=computed(()=>{const esc=(v:string)=>v.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');const body=esc(tdd.value).replace(/^### (.*)$/gm,'<h3>$1</h3>').replace(/^## (.*)$/gm,'<h2>$1</h2>').replace(/^# (.*)$/gm,'<h1>$1</h1>').replace(/^- (.*)$/gm,'<li>$1</li>').replace(/\n\n/g,'</p><p>').replace(/\n/g,'<br>');return `<!doctype html><html><head><meta charset="utf-8"><style>body{font:14px/1.6 Arial,sans-serif;color:#172033;max-width:900px;margin:0 auto;padding:32px}h1{font-size:28px;border-bottom:2px solid #0b8a5f;padding-bottom:10px}h2{margin-top:28px;color:#0b8a5f}h3{margin-top:20px}li{margin:4px 0}p{margin:10px 0}</style></head><body><p>${body}</p></body></html>`})
function selectApi(id:string){selected.value=id;router.replace({path:'/docs',query:{id}})}
function newVersion(){if(api.value)router.push({path:'/create',query:{extend:api.value.id}})}
async function copy(){try{await navigator.clipboard.writeText(yaml.value)}catch{globalThis.window?.alert('Clipboard unavailable — use Download YAML instead')}}
function previewTdd(){previewOpen.value=!previewOpen.value}
</script>
<template>
<h1>API Documentation</h1><p class="sub">Owner, lifecycle, operations and OpenAPI spec for every API in the catalog.</p>
<div class="doc-layout"><aside class="doc-catalog card"><label for="doc-search">Search APIs</label><input id="doc-search" v-model="query" placeholder="Search APIs by name, team or backend…"/><div class="stack doc-picks"><button v-for="a in choices" :key="a.id" class="card pick" :class="{on:selected===a.id}" @click="selectApi(a.id)"><div class="toolbar"><b>{{a.name}} <span class="ver">{{a.version}}</span></b><span class="tag" :class="'st-'+a.status">{{a.status}}</span></div><div class="small mu">{{a.team}} · {{a.ops.length}} operations</div></button><div v-if="!choices.length" class="empty">No APIs found</div></div></aside>
<div v-if="api" class="doc-main"><section class="card"><div class="toolbar"><div><h2 style="margin:0">{{api.name}} <span class="ver">{{api.version}}</span> <span class="tag" :class="'st-'+api.status">{{api.status}}</span></h2><p>{{api.desc}}</p></div><button class="btn ghost sm" @click="newVersion">+ New version</button></div><table><tbody><tr><th>Backend endpoint</th><td><code>{{api.backend}}</code></td></tr><tr><th>Gateway URL suffix</th><td><code>{{api.suffix}}</code></td></tr><tr><th>Owning team</th><td>{{api.team}}<span v-if="api.contact"> · <a :href="`mailto:${api.contact}`">{{api.contact}}</a></span></td></tr><tr><th>Authentication</th><td>{{api.auth==='oauth'?'OAuth 2.0 (bearer JWT)':'Subscription key'}}</td></tr><tr><th>Consumers</th><td>{{api.consumers}}</td></tr><tr><th>Operations</th><td>{{api.ops.length}}</td></tr><tr><th>Spec file</th><td><code>{{api.specFile||'Not committed'}}</code><span v-if="api.specFile"> in <code>{{s.settings.repo}}</code></span></td></tr><tr v-if="api.codeRepo"><th>Service code repo</th><td><a :href="api.codeRepo" target="_blank" rel="noreferrer"><code>{{api.codeRepo}}</code></a></td></tr><tr v-if="api.vault"><th>Key Vault named value</th><td><code>{{api.vault}}</code></td></tr><tr><th>Source</th><td>{{api.origin==='created'?'Created with API Creation':'Existing API'}}</td></tr><tr v-if="lastPr"><th>Latest PR</th><td><span class="tag ok">#{{lastPr.id}} {{lastPr.kind}}</span> · <code>{{lastPr.branch}}</code> · commit <code>{{lastPr.sha}}</code></td></tr></tbody></table></section>
<section class="card"><h2>Operations</h2><div class="scroll"><table><thead><tr><th>Method</th><th>Path</th><th>Operation ID</th><th>Summary</th></tr></thead><tbody><tr v-for="(op,i) in api.ops" :key="op[0]+op[1]+i"><td><span class="m" :class="op[0]">{{op[0]}}</span></td><td><code>{{op[1]}}</code></td><td><code>{{op[3]||ids[i]}}</code></td><td>{{op[2]||'Operation'}}</td></tr></tbody></table></div><div class="actions"><button class="btn" @click="download(specFilename(api),yaml,'application/yaml')">Download OpenAPI</button><button class="btn ghost sm" @click="copy">Copy YAML</button></div></section>
<section class="card"><h2>Technical design document (TDD)</h2><p class="mu">Generate a TDD pre-filled from this API’s OpenAPI spec. Anything the spec can’t answer is marked [TBD] for the team to complete.</p><label for="tdd-template">Template</label><select id="tdd-template" v-model="templateId"><option v-for="t in templates" :key="t.id" :value="t.id">{{t.name}}{{t.id==='process'?' (default)':''}}</option></select><p class="small mu">{{templateDescription}}</p><details class="tdm"><summary>Document details (optional: author, JIRA, source and target systems)</summary><div class="row"><input placeholder="Author"/><input placeholder="JIRA / tracking ID"/></div><div class="row"><input placeholder="Source system"/><input placeholder="Target system"/></div></details><pre>{{tdd}}</pre><div class="actions"><button class="btn ghost sm" @click="previewTdd">{{previewOpen?'Hide preview':'Preview'}}</button><button class="btn sm" @click="download(`TDD-${slug(api.name)}.doc`,tdd,'application/msword')">Download Word (.doc)</button><button class="btn ghost sm" @click="download(`TDD-${slug(api.name)}.md`,tdd,'text/markdown')">Markdown (.md)</button><span class="small mu">{{tbdCount}} items marked [TBD]</span></div><iframe v-if="previewOpen" class="tdd-prev" sandbox="" :srcdoc="previewHtml" title="TDD preview"></iframe></section>
<section class="card live"><div class="toolbar"><h2 style="margin:0">OpenAPI 3.0 spec</h2><div class="actions" style="margin:0"><button class="btn ghost sm" @click="copy">Copy</button><button class="btn ghost sm" @click="download(specFilename(api),yaml,'application/yaml')">Download .yaml</button></div></div><pre>{{yaml}}</pre></section></div></div>
</template>
